package store.cadera.cdrjobs.util;
import store.cadera.cdrjobs.CdrJobsPlugin;
public final class ConfigValidator {private ConfigValidator(){}public static void validate(CdrJobsPlugin p){int max=p.getConfig().getInt("settings.max-level",100);if(max<1)p.getLogger().warning("settings.max-level must be >= 1; runtime will clamp where possible.");double base=p.getConfig().getDouble("settings.xp-curve.base-xp",100);if(base<=0)p.getLogger().warning("XP curve base should be > 0.");for(String job:new String[]{"miner","farmer","hunter","lumberjack","fisher"}){double m=p.getConfig().getDouble(job+".xp-multiplier",1);if(m<0)p.getLogger().warning(job+".xp-multiplier is negative; rewards will be clamped.");}long afk=p.getConfig().getLong("fisher.anti-exploit.afk-after-seconds",600);if(afk<60)p.getLogger().warning("Fisher AFK threshold below 60s is aggressive and may cause false positives.");}}
